export const DEMO_VN_EN: VisualNovel = {
  ...DEMO_VN,
  title: "The Abyssal Library: Forbidden Knowledge",
  description: "You arrive at the Abyssal Library in search of your missing historian father. Your choices may reveal the truth, or leave you trapped in darkness forever.",
  contentLanguage: 'en',
  characters: DEMO_VN.characters.map(character => ({ ...character, ...DEMO_VN_EN_CHARACTERS[character.id] })),
  scenes: DEMO_VN.scenes.map(scene => {
    const text = DEMO_VN_EN_SCENES[scene.id];
    return {
      ...scene,
      name: text.name,
      dialogue: scene.dialogue.map((line, index) => ({ ...line, text: text.dialogue[index] })),
      choices: scene.choices.map((choice, index) => ({ ...choice, text: text.choices[index] })),
    };
  }),
};

/** Japanese falls back to the English demo story. */
export function getDemoVn(language: string): VisualNovel {
  return language === 'ko' ? DEMO_VN : DEMO_VN_EN;
}

