/** EMPTY_VN with its four visible texts passed through the UI translator. */
export function getEmptyVn(t: (source: string) => string): VisualNovel {
  return {
    ...EMPTY_VN,
    title: t(EMPTY_VN.title),
    description: t(EMPTY_VN.description),
    scenes: EMPTY_VN.scenes.map(scene => ({
      ...scene,
      name: t(scene.name),
      dialogue: scene.dialogue.map(line => ({ ...line, text: t(line.text) })),
    })),
  };
}
